const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry for Naivasha, Kenya
  const naivasha = ee.Geometry.Point(36.4333, -0.7167).buffer(20000); // 20km buffer

  // 2. Load GHSL built-up dataset (global, 30m resolution)
  const ghsl = ee.Image('JRC/GHSL/P2016/S1_Built_LDSMT_GLOBE_V1');

  // Select bands for 1990 (proxy for 1986) and 2000
  const built1990 = ghsl.select('built_s1_1990');
  const built2000 = ghsl.select('built_s1_2000');

  // Check if bands exist (C1 scenario unlikely but possible)
  const bandList = ghsl.bandNames().getInfo();
  if (!bandList.includes('built_s1_1990') || !bandList.includes('built_s1_2000')) {
    print('C1: Required bands not found in dataset.');
    print('<answer>C1</answer>');
    return;
  }

  // 3. Compute sum of built-up pixels (values: 0 or 1)
  const reduceConfig = {
    reducer: ee.Reducer.sum(),
    geometry: naivasha,
    scale: 100, // Using 100m scale for efficiency (native is 30m)
    maxPixels: 1e9,
    bestEffort: true
  };

  const sum1990 = built1990.reduceRegion(reduceConfig).get('built_s1_1990');
  const sum2000 = built2000.reduceRegion(reduceConfig).get('built_s1_2000');

  // Get values (handle potential nulls)
  let val1990, val2000;
  try {
    val1990 = sum1990.getInfo();
    val2000 = sum2000.getInfo();
  } catch (e) {
    print('C3: Failed to retrieve reduction results.');
    print('<answer>C3</answer>');
    return;
  }

  // Check for valid numbers
  if (val1990 === null || val2000 === null || 
      isNaN(val1990) || isNaN(val2000)) {
    print('C3: Result is null or NaN.');
    print('<answer>C3</answer>');
    return;
  }

  // Convert pixel count to area (km²): 1 pixel = 30m × 30m = 900 m² = 0.0009 km²
  // Adjust for scale: if scale=100m, pixel area = 10000 m² = 0.01 km²
  // But the reducer sums the 30m pixels within each 100m pixel? Actually, using scale=100 
  // will resample the 30m data to 100m, so we need to adjust the area factor.
  // Safer: use native 30m scale, but for speed we use 100m and adjust factor.
  // Since we used scale=100, each output pixel represents 100m×100m = 0.01 km².
  // The built-up values are 0 or 1, but when resampled to 100m, the sum is fractional.
  // To get accurate area, we should use native 30m scale. Let's switch to 30m.

  // Recompute with 30m scale for accuracy
  const reduceConfig30 = {
    reducer: ee.Reducer.sum(),
    geometry: naivasha,
    scale: 30,
    maxPixels: 1e9,
    bestEffort: true
  };

  const sum1990_30 = built1990.reduceRegion(reduceConfig30).get('built_s1_1990');
  const sum2000_30 = built2000.reduceRegion(reduceConfig30).get('built_s1_2000');

  let val1990_30, val2000_30;
  try {
    val1990_30 = sum1990_30.getInfo();
    val2000_30 = sum2000_30.getInfo();
  } catch (e) {
    print('C3: Failed to retrieve 30m reduction results.');
    print('<answer>C3</answer>');
    return;
  }

  if (val1990_30 === null || val2000_30 === null || 
      isNaN(val1990_30) || isNaN(val2000_30)) {
    print('C3: 30m result is null or NaN.');
    print('<answer>C3</answer>');
    return;
  }

  // Area in km²: each 30m pixel = 0.0009 km²
  const area1990 = val1990_30 * 0.0009;
  const area2000 = val2000_30 * 0.0009;

  // 4. Output evidence
  print(`1990 (proxy for 1986) Built-up pixels: ${val1990_30.toFixed(0)}`);
  print(`2000 Built-up pixels: ${val2000_30.toFixed(0)}`);
  print(`1990 Urban area: ${area1990.toFixed(2)} km²`);
  print(`2000 Urban area: ${area2000.toFixed(2)} km²`);

  // 5. Determine answer
  if (area2000 > area1990) {
    print('<answer>A</answer>');
  } else {
    print('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
